from pathlib import Path
import json,html
root=Path('docs/audits/typography-2026-11-01/sentence-case')
specs=[
('plan','Reading-plan overview','Day heading and detail action: system sans, 14sp Medium (500).','Date and detail action now keep their supplied sentence case.'),
('plan-list','Reading-plan list','UI labels: system sans, 14sp Medium (500); reading references: 16sp Regular (400).','Date and action labels use sentence case in the plan detail flow.'),
('plan-date','Reading-plan date menu','Day heading and detail action: system sans, 14sp Medium (500).','The date heading and detail action no longer force capitals.'),
('bookmark-editor','Bookmark editor','Label heading and actions: system sans, 14sp Medium (500); caption field: 16sp Regular (400).','Labels becomes sentence case. Native dialog actions preserve the localized wording.'),
('color-sliders','Color sliders','Channel labels: system sans, 14sp Medium (500); values: 14sp Regular (400).','Color names use sentence case. Hexadecimal values retain their technical notation.'),
('goto-direct-candidates','Direct reference entry','Prompt: system sans, 16sp Regular (400), with inline bold emphasis; suggestions: 16sp Medium (500).','The prompt changes from LONCAT KE to Loncat ke, with its emphasis retained.'),
('version-details','Version metadata dialog','Metadata label: bold (700), 0.7× the dialog body size; existing dialog body typography is retained.','Metadata labels no longer convert to uppercase. Version names and technical identifiers retain their casing.'),
('legacy-sign-in','Native sign-in','Action labels: system sans, 14sp Medium (500); fields: 16sp Regular (400).','Native action buttons preserve sentence case through the shared platform and AppCompat styles.'),
('debug-sync','Developer sync controls','Actions: system sans, 14sp Medium (500); explanatory text: 14sp Regular (400).','Action labels and section names no longer force capitals. Diagnostic codes retain their supplied casing. No action is invoked in this capture.'),
('song-search','Song search','Search field: 16sp Regular (400); filter labels: 14sp Medium (500).','The All/Semua songbook label is sentence case.'),
('song-case-fixture','Song text component fixture','Tune: sans serif, 17.5dp Regular (400); copyright: 15dp Bold (700); body: serif, 20dp Regular (400).','Production song renderer with fixed mixed-case source text. Tune names and copyright retain source casing. This is a component fixture, not a downloaded song.'),
('goto-dialer','Bible keypad, selected Option A','Book: 16sp Medium (500); entered values: 24sp Medium (500); digits: 28sp Medium (500); confirmation: 14sp Medium (500).','The selected outlined field remains. The confirmation label uses Ok.'),
('legacy-goto-dialer','Native Bible keypad','Book: 16sp Medium (500); values: 24sp Medium (500); digits: 28sp Medium (500); confirmation: 14sp Medium (500).','Native keypad confirmation follows the same sentence-case rule.'),
('song-selector','Song keypad, selected Option A','Book: 16sp Medium (500); value: 24sp Medium (500); digits: 28sp Medium (500); confirmation: 14sp Medium (500).','The selected outlined field remains. The confirmation label uses Ok; suffix letters A/B/C remain functional identifiers.'),
('song-drawer','Native song drawer','Book: 16sp Medium (500); value: 24sp Medium (500); digits: 28sp Medium (500); confirmation: 16sp Medium (500).','Native song controls preserve sentence case while keeping songbook codes and suffix letters.'),
('report-verse','Verse report','Action label: system sans, 14sp Medium (500); reference: 16sp Regular (400).','The form retains its casing. The colored submit action is below this viewport and is verified separately by the API 26/34 native-control regression checks. No report is submitted.'),
('plan-catalog','Reading-plan download catalog','Owned WebView catalog: tabs 14px Medium (500), body 16px Regular (400); actions retain the page sizing.','The scoped catalog adapter disables uppercase CSS and normalizes uppercase action/tab labels, preserving technical terms such as ID and JSON. No server deployment is required.'),
('song-catalog','Songbook download catalog','Owned WebView catalog: tabs 14px Medium (500), body/name 16px Regular (400), descriptions 14px Regular (400).','The same scoped sentence-case rule applies to the songbook catalog; source songbook names are retained.'),
]
(root/'screens.json').write_text(json.dumps([dict(id=x[0],title=x[1],font=x[2],note=x[3]) for x in specs],indent=2,ensure_ascii=False)+'\n')
style='*{box-sizing:border-box}body{margin:0;background:#eef2f5;color:#213747;font:16px/1.5 system-ui,sans-serif}main{max-width:1150px;margin:auto;padding:28px}header,article,.intro{padding:24px;margin-bottom:24px;background:white;border:1px solid #d4dfe5;border-radius:14px}h1{font-size:32px;line-height:1.2}h2{font-size:23px}a{color:#006e8b}nav{display:flex;flex-wrap:wrap;gap:10px 18px}.shots{display:grid;grid-template-columns:1fr 1fr;gap:20px;max-width:800px;margin:20px auto}figure{margin:0;min-width:0}img{display:block;width:100%;height:auto;max-width:360px;margin:auto}figcaption{text-align:center;font-size:14px;font-weight:600;margin-bottom:8px}.raw{display:block;text-align:center;font-size:12px;margin-top:8px}.font{padding:12px;background:#edf5f8;border-left:3px solid #1587a1;font-size:14px}.note{font-size:14px}article{scroll-margin-top:18px}.tag{font-size:13px;color:#276578;font-weight:600}@media(max-width:650px){main{padding:12px}header,article,.intro{padding:16px}.shots{gap:10px}h1{font-size:27px}}'
parts=['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AndroidBible sentence-case UI</title><meta name="description" content="Sentence-case app controls and labels, with selected Option A and annotated Android comparisons."><style>'+style+'</style></head><body><main><header><span class="tag">Latest typography revision • 2 November 2026</span><h1>Sentence-case UI, with Option A selected</h1><p>Forced uppercase styling has been removed from app controls and headings. UI labels stored in capitals now use sentence case across the existing translations. Option A, the outlined number field, is the selected design.</p><nav><a href="https://androidbible-typography-review.itikku.chatgpt.site/accessibility/">Selected Option A and earlier Medium-weight evidence</a><a href="https://github.com/yukuku/androidbible/pull/375">Review PR #375</a><a href="https://androidbible-typography-review.itikku.chatgpt.site/">Initial 75-pair snapshot</a></nav></header><section class="intro"><h2>What changed</h2><p>Platform, AppCompat, Material, colored and outlined buttons preserve sentence case, including native dialog actions. Reading-plan dates/actions, version metadata labels, color-channel names, bookmark labels, and songbook All labels follow the same rule. Tune names and copyright are no longer converted to capitals in song rendering or copy/share output. The owned download catalogs override uppercase CSS.</p><p>175 localized labels or label segments were normalized in 26 locale files. Source content and identifiers such as BIMK, KJ, song suffixes, testament abbreviations, and hexadecimal values retain their proper casing.</p><p>These comparisons retain font size and weight unless the inherited native button appearance needed the shared 14sp Medium action role. Raw screenshots are unretouched. Keyboard visibility, status-bar details, and asynchronous content can differ independently of casing. Eleven baseline states were captured immediately before this change; the remaining baselines are retained earlier typography snapshots and are identified below. The song case is a production-component fixture.</p><nav>']
parts += [f'<a href="#{i}">{html.escape(t)}</a>' for i,t,_,_ in specs]
parts+=['</nav></section>']
for i,title,font,note in specs:
 if not (root/'after'/f'{i}.png').exists():raise RuntimeError('Missing after '+i)
 retained=i in ['goto-dialer','legacy-goto-dialer','song-selector','song-drawer','report-verse','plan-catalog','song-catalog']
 parts.append(f'<article id="{i}"><h2>{html.escape(title)}</h2><p>{html.escape(note)}</p><div class="shots">')
 for phase in ['before','after']:
  src=f'{phase}/{i}.png'
  parts.append(f'<figure><figcaption>{"Before" if phase=="before" else "After"} · {"retained typography snapshot" if phase=="before" and retained else "previous app" if phase=="before" else "sentence-case UI"}</figcaption><img src="{src}" alt="{html.escape(title)}: {phase}"><a class="raw" href="{src}">Open raw screenshot</a></figure>')
 parts.append('</div><p class="font"><strong>Typography:</strong> '+html.escape(font)+'</p></article>')
parts.append('<section class="intro"><h2>Verification and limits</h2><p>App/test APK builds, focused typography/navigation/song tests, and Android lint were checked. Captures use Android CLI installation and device-specific Instrumentation on the dedicated Android 15 emulator at 720 × 1280, 320dpi, and 100% system font size. No sign-in, report, feedback, or destructive developer action was submitted. The 200% layout work remains outside scope.</p><p>The final generic-alert and date-picker confirmation wording was checked on API 26/34. Its final-label emulator recapture timed out during process startup, so that state is excluded from these comparisons.</p><p>These captures record the casing revision before the latest develop integration. That integration retains the newer dark container palette and dialog/Note layout fixes. Those inherited changes were not recaptured here.</p><p><a href="integration-validation.json">After develop integration: app/test builds, lint, and 46 focused test executions passed</a>.</p><p><a href="validation.json">Browser verification</a> · <a href="manifest.json">Capture provenance</a> · <a href="localized-changes.json">Localized label changes</a> · <a href="unit-tests.json">Focused test results</a></p></section></main></body></html>')
(root/'index.html').write_text(''.join(parts))
print('Built',len(specs),'comparison pairs')
